sp_widget.client_script:
api.controller = function($scope, $interval, $window, $timeout, $rootScope) { // Adicionado $timeout

	 var c = this;

	  // Escuta o evento emitido
$rootScope.$on('sp.contrast.toggled', function(event, data) {
	console.log('Contraste alterado:', data.enabled);
  // Pega o container principal do carrossel
  var viewport = document.querySelector('.card-viewport');
	var statCards  = document.querySelectorAll('.stat-card');
	var mainTitle = document.querySelector('.main-title');
	var subTitle = document.querySelector('.sub-title');
	var btnMore = document.querySelector('.btn-more');
	var indicadoresPontos = document.querySelectorAll('.indicadoresPontos');
	var badge = document.querySelector('.badge-cat');
	var bannerBg = document.querySelector('.banner-bg');
	var bannerOverlay = document.querySelector('.banner-overlay');
  if (!viewport) return;

  if (data.enabled) {
    viewport.classList.add('high-contrast');
		 statCards.forEach(function(card) {
      card.classList.add('high-contrast');
    });
		mainTitle.classList.add('high-contrast');
		subTitle.classList.add('high-contrast');
		btnMore.classList.add('high-contrast');

		indicadoresPontos.forEach(function(card) {
      card.classList.add('high-contrast');
    });
			badge.classList.add('high-contrast');

		// Trocar imagem de fundo para modo contraste
		if (bannerBg) {
			bannerBg.style.backgroundImage = "url('/x_sded9_portal_t_0.imgContrastbanner.png')";
		}

		// Adicionar classe high-contrast ao overlay
		if (bannerOverlay) {
			bannerOverlay.classList.add('high-contrast');
		}

  } else {
    viewport.classList.remove('high-contrast');
		statCards.forEach(function(card) {
      card.classList.remove('high-contrast');
    });
		mainTitle.classList.remove('high-contrast');
		subTitle.classList.remove('high-contrast');
		btnMore.classList.remove('high-contrast');

		indicadoresPontos.forEach(function(card) {
      card.classList.remove('high-contrast');
    });
			badge.classList.remove('high-contrast');

		// Voltar para imagem de fundo normal
		if (bannerBg) {
			bannerBg.style.backgroundImage = "url('/x_sded9_portal_t_0.img_sefaz.png')";
		}

		// Remover classe high-contrast do overlay
		if (bannerOverlay) {
			bannerOverlay.classList.remove('high-contrast');
		}
  }
});


	/*===============================*/
	var autoRotateInterval;

    // Dados unificados para todos os cards
    $scope.cardData = [
        {
            id: 1,
            badge_icon: "fa-solid fa-medal",
            badge_text: "DESTAQUE NACIONAL",
            title: "NOTA A",
            subtitle: "EM GESTÃO FISCAL NO PAÍS",
            description: "Melhor classificação entre os estados brasileiros"
        },
        {
            id: 2,
            badge_icon: "fa-chart-line",
            badge_text: "MAIOR REDUÇÃO DO BRASIL",
            title: "-4,77 bi",
            subtitle: "REDUÇÃO DA DÍVIDA PÚBLICA",
            description: "A menor dívida líquida do país"
        },
        {
            id: 3,
            badge_icon: "fa-plus-circle",
            badge_text: "SOLIDEZ FISCAL",
            title: "Top 2",
            subtitle: "EM SOLIDEZ FISCAL NO PAÍS",
            description: "2º melhor Estado do Brasil em solidez fiscal"
        },
        {
            id: 4,
            badge_icon: "fa-solid fa-money-bill-trend-up",
            badge_text: "CONTROLE DE EMPENHO",
            title: "R$ 39 BI",
            subtitle: "EM EMPENHOS EFETIVADOS",
            description: "Controle total do volume das despesas realizadas pelo Estado"
        }
    ];

    $scope.activeIndex = 0;
    $scope.sideCards = [];

    // Função para atualizar os cards da direita
    $scope.updateSideCards = function() {
        $scope.sideCards = [];

        // Obter os próximos 3 cards após o ativo (com loop circular)
        for (var i = 1; i <= 3; i++) {
            var index = ($scope.activeIndex + i) % $scope.cardData.length;
            $scope.sideCards.push($scope.cardData[index]);
        }
    };

    // Função para determinar a classe de cada card no carrossel principal
    $scope.getCardClass = function(index) {
        if (index === $scope.activeIndex) {
            return 'is-main';
        } else if ((index - $scope.activeIndex + $scope.cardData.length) % $scope.cardData.length === 1) {
            return 'is-side-1';
        } else if ((index - $scope.activeIndex + $scope.cardData.length) % $scope.cardData.length === 2) {
            return 'is-side-2';
        } else if ((index - $scope.activeIndex + $scope.cardData.length) % $scope.cardData.length === 3) {
            return 'is-side-3';
        } else {
            return 'is-hidden';
        }
    };

    // Nova função centralizada para trocar de slide
    $scope.changeSlide = function(newIndex) {
        // 1. Identificar o card que está saindo (o atual principal)
        var outgoingCard = $scope.cardData[$scope.activeIndex];
        // 2. Marcar esse card para animação
        outgoingCard.shouldAnimate = true;

        // 3. Atualizar o índice ativo
        $scope.activeIndex = newIndex;
        // 4. Atualizar a lista de cards da direita
        $scope.updateSideCards();

        // 5. Limpar a flag de animação após um curto período
        // Isso garante que a animação só ocorra uma vez
        $timeout(function() {
            outgoingCard.shouldAnimate = false;
        }, 1000); // Tempo deve ser >= duração da animação CSS
    };

    $scope.goToCard = function(index) {
        $scope.changeSlide(index);
    };

    $scope.nextSlide = function() {
        var newIndex = ($scope.activeIndex + 1) % $scope.cardData.length;
        $scope.changeSlide(newIndex);
    };

    $scope.prevSlide = function() {
        var newIndex = ($scope.activeIndex - 1 + $scope.cardData.length) % $scope.cardData.length;
        $scope.changeSlide(newIndex);
    };

    // Nova função para lidar com cliques nos cards da direita
    $scope.goToSideCard = function(index) {
        var targetIndex = ($scope.activeIndex + index + 1) % $scope.cardData.length;
        $scope.goToCard(targetIndex);
    };

    // Função para abrir o link "Saiba mais" do card principal
    $scope.openMoreInfo = function(event) {
        event.stopPropagation();
        var instanceName = window.location.hostname.split('.')[0];
        var url = 'https://' + instanceName + '.service-now.com/sate?id=404_sefaz';
        $window.open(url, '_blank');
    };

    // Rotação Automática
    function startAutoRotate() {
        stopAutoRotate();
        autoRotateInterval = $interval(function() {
            $scope.nextSlide();
        }, 5000);
    }

    function stopAutoRotate() {
        if (angular.isDefined(autoRotateInterval)) {
            $interval.cancel(autoRotateInterval);
            autoRotateInterval = undefined;
        }
    }

    $scope.pauseAutoRotate = function() {
        stopAutoRotate();
    };

    $scope.resumeAutoRotate = function() {
        startAutoRotate();
    };

    // Inicializar os cards da direita
    $scope.updateSideCards();

    startAutoRotate();

    $scope.$on('$destroy', function() {
        stopAutoRotate();
    });
};

sp_widget.css:
/* === Adiciona Font Awesome para ícones === */
@import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/css/all.min.css');
@import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css');
@font-face {
  font-family: 'Roboto Flex';
  /* src: url('...'); */
  font-weight: 400;
  font-style: normal;
}
/* === Container Principal e Reset === */
.mt-fiscal-banner {
  position: relative;
  width: 100%;
  height: 600px;
  overflow: hidden;
  font-family: "Roboto Flex", Arial, sans-serif;
  color: white;
  z-index: 5;
  margin-top: -24px
}

.mt-fiscal-banner * {
  box-sizing: border-box;
  font-family: 'Roboto Flex', sans-serif !important;
}

/* === Fundo e Gradiente === */
.mt-fiscal-banner .banner-bg {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  background-image: url('/x_sded9_portal_t_0.img_sefaz.png');
  background-size: cover;
  background-position: center;
  z-index: 1;
}

.mt-fiscal-banner .banner-overlay {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  background: radial-gradient(circle, rgba(16, 51, 117, 0.85) 0%, rgba(8, 25, 66, 0.95) 100%);
  z-index: 2;
}

.mt-fiscal-banner .banner-overlay.high-contrast {
  background: radial-gradient(circle, rgba(2, 2, 2, 0.55) 0%, rgba(0, 0, 0, 0.95) 100%) !important;
}

/* === Layout Flexbox === */
.mt-fiscal-banner .main-content {
  position: relative; z-index: 10; height: 100%;
  display: flex; align-items: center; padding: 0 4%;
  gap: 2%;
}

.mt-fiscal-banner .left-column {
  flex-basis: 60%;
  display: flex; flex-direction: column; justify-content: center;
}

.mt-fiscal-banner .right-column {
  flex-basis: 15%;
  display: flex; flex-direction: column; justify-content: center;
  gap: 16px;
}

/* Animação para os cards da direita */
@keyframes slideInRight {
  from {
    transform: translateX(100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes slideOutLeft {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(-100%);
    opacity: 0;
  }
}

.mt-fiscal-banner .stat-card.animate-in {
  animation: slideInRight 0.5s ease forwards;
}

.mt-fiscal-banner .stat-card.animate-out {
  animation: slideOutLeft 0.5s ease forwards;
}


@media screen and (max-width: 1800px) {
  .mt-fiscal-banner .main-content,
  .mt-fiscal-banner.high-contrast .main-content {
    padding: 20px 2%;
  }

  .mt-fiscal-banner .left-column,
  .mt-fiscal-banner.high-contrast .left-column {
    flex-basis: 65%;
  }

  .mt-fiscal-banner .right-column,
  .mt-fiscal-banner.high-contrast .right-column {
    flex-basis: 265px;
    flex-grow: 0;
    flex-shrink: 0;
  }
}


@media screen and (max-width: 768px) {
  .mt-fiscal-banner,
  .mt-fiscal-banner.high-contrast {
    height: 500px;
  }

  .mt-fiscal-banner .main-content,
  .mt-fiscal-banner.high-contrast .main-content {
    padding: 15px 1%;
    position: relative;
    z-index: 10;
    height: 100%;
    display: flex;
    align-items: center;
    padding: 0 4%;
    gap: 2%;
  }

  .mt-fiscal-banner .left-column,
  .mt-fiscal-banner.high-contrast .left-column {
    flex-basis: 100%;
    margin-bottom: -25px;
  }

  .mt-fiscal-banner .right-column,
  .mt-fiscal-banner.high-contrast .right-column {
    display: none; /* Oculta os cards da direita em telas menores */
  }

  .mt-fiscal-banner .card-viewport,
  .mt-fiscal-banner.high-contrast .card-viewport {
    height: 220px;
  }

  .mt-fiscal-banner .info-card,
  .mt-fiscal-banner.high-contrast .info-card {
    padding: 20px 25px;
  }

  /* Garante que apenas o card principal seja visível */
  .mt-fiscal-banner .info-card:not(.is-main),
  .mt-fiscal-banner.high-contrast .info-card:not(.is-main) {
    display: none;
  }

  .mt-fiscal-banner .main-title,
  .mt-fiscal-banner.high-contrast .main-title {
    font-size: 3rem;
  }

  .mt-fiscal-banner .sub-title,
  .mt-fiscal-banner.high-contrast .sub-title {
    font-size: 1.4rem;
  }

  .mt-fiscal-banner .banner-header,
  .mt-fiscal-banner.high-contrast .banner-header {
    margin-left: 10px;
    margin-bottom: 20px;
  }

  .mt-fiscal-banner .indicators,
  .mt-fiscal-banner.high-contrast .indicators {
    padding-left: 0;
    justify-content: center;
    margin-top: 30px;
  }
}

/* Correção específica para o range 481px-769px para evitar texto cortado */
@media screen and (min-width: 481px) and (max-width: 769px) {
  .mt-fiscal-banner .main-title,
  .mt-fiscal-banner.high-contrast .main-title {
    font-size: 2.8rem;
    line-height: 1.1;
  }

  .mt-fiscal-banner .sub-title,
  .mt-fiscal-banner.high-contrast .sub-title {
    font-size: 1.3rem;
    line-height: 1.2;
  }

  .mt-fiscal-banner .banner-header,
  .mt-fiscal-banner.high-contrast .banner-header {
    margin-left: 15px;
    margin-bottom: 25px;
  }

  .mt-fiscal-banner,
  .mt-fiscal-banner.high-contrast {
    height: 520px; /* Aumenta ligeiramente a altura para acomodar melhor o texto */
  }

  /* High-contrast rules for 481px-769px */
  .mt-fiscal-banner .main-title.high-contrast,
  .mt-fiscal-banner .sub-title.high-contrast {
    //color: #000000 !important;
  }

  .mt-fiscal-banner .badge-cat.high-contrast {
    background-color: #838383 !important;
    color: black !important;
  }

  .mt-fiscal-banner .badge-cat.high-contrast .yellow {
    color: white !important;
  }
}

@media screen and (max-width: 576px) {
  .mt-fiscal-banner,
  .mt-fiscal-banner.high-contrast {
    height: 450px;
  }

  .mt-fiscal-banner .main-content,
  .mt-fiscal-banner.high-contrast .main-content {
    padding: 10px 1%;
  }

  .mt-fiscal-banner .left-column,
  .mt-fiscal-banner.high-contrast .left-column {
    flex-basis: 100%;
    margin-bottom: 90px;
  }

  .mt-fiscal-banner .right-column,
  .mt-fiscal-banner.high-contrast .right-column {
    display: none; /* Oculta os cards da direita */
  }

  .mt-fiscal-banner .card-viewport,
  .mt-fiscal-banner.high-contrast .card-viewport {
    height: 200px;
  }

  .mt-fiscal-banner .info-card,
  .mt-fiscal-banner.high-contrast .info-card {
    padding: 15px 20px;
  }

  /* Garante que apenas o card principal seja visível */
  .mt-fiscal-banner .info-card:not(.is-main),
  .mt-fiscal-banner.high-contrast .info-card:not(.is-main) {
    display: none;
  }

  .mt-fiscal-banner .nav-btn,
  .mt-fiscal-banner.high-contrast .nav-btn {
    width: 35px;
    height: 35px;
  }

  .mt-fiscal-banner .main-title,
  .mt-fiscal-banner.high-contrast .main-title {
    font-size: 2.8rem;
  }

  .mt-fiscal-banner .sub-title,
  .mt-fiscal-banner.high-contrast .sub-title {
    font-size: 1.3rem;
  }

  .mt-fiscal-banner .badge-cat,
  .mt-fiscal-banner.high-contrast .badge-cat {
    font-size: 1.5rem;
    padding: 6px 12px;
  }

  .mt-fiscal-banner .indicators,
  .mt-fiscal-banner.high-contrast .indicators {
    padding-left: 0;
    justify-content: center;
    margin-top: 25px;
  }

  /* Regra específica para mover botão "Saiba mais" para baixo nos cards "-4,77 bi" e "top 2" */
  .mt-fiscal-banner .info-card .btn-more,
  .mt-fiscal-banner.high-contrast .info-card .btn-more {
    margin-top: 15px;
    margin-bottom: 10px;
  }
}

/* === Cabeçalho === */
.mt-fiscal-banner .banner-header {
  margin-bottom: 30px;
  background: transparent !important;
  margin-left: 48px;
}

.mt-fiscal-banner .main-title,
.mt-fiscal-banner .sub-title {
  color: white !important;
}

.mt-fiscal-banner .main-title {
  font-size: 5rem; font-weight: 900; margin: 0; line-height: 1; text-transform: uppercase;
}
.mt-fiscal-banner .sub-title {
  font-size: 2.2rem; font-weight: normal; margin: 5px 0 15px 0; opacity: 0.9;
}
.mt-fiscal-banner .badge-cat {
  display: inline-block; background-color: #808bb8;
  padding: 8px 15px; border-radius: 8px; font-weight: 700;
  font-size: 1.9rem;
}
.mt-fiscal-banner .yellow { color: #f0f32e; }

/* === Carrossel === */
.mt-fiscal-banner .carousel-wrapper {
  display: flex; align-items: center; max-width: 550px;
}
.mt-fiscal-banner .nav-btn {
  background: transparent; border: 2px solid rgba(255,255,255,0.8);
  color: white; width: 45px; height: 45px; border-radius: 50%;
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  transition: all 0.3s; flex-shrink: 0;
  position: relative;
}
.mt-fiscal-banner .nav-btn:hover { background: rgba(255,255,255,0.2); }
.mt-fiscal-banner .nav-btn.prev { 
  z-index: 20;
}
.mt-fiscal-banner .nav-btn.next { 
  z-index: 20;
}
.mt-fiscal-banner .card-viewport {
  flex-grow: 1; position: relative; height: 330px;
}

/* === Cartões com Animações === */
.mt-fiscal-banner .info-card {
  background: white; color: #333; border-radius: 25px;
  padding: 30px 40px; box-shadow: 0 10px 30px rgba(0,0,0,0.3);
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  transition: all 0.7s cubic-bezier(0.25, 0.8, 0.25, 1);
  z-index: 1;
  opacity: 0;
  transform: scale(0.9) translateY(20px);
  display: flex;
  flex-direction: column;
}

.mt-fiscal-banner .info-card.is-main {
  opacity: 1;
  transform: scale(1) translateY(0);
  z-index: 3;
}

.mt-fiscal-banner .info-card.is-hidden {
  opacity: 0;
  transform: scale(0.8) translateX(-100px);
  z-index: 0;
  display: none; /* Esconde completamente os cards ocultos */
}

.mt-fiscal-banner .info-card.is-side-1 {
  opacity: 0.8;
  transform: scale(0.9) translateY(10px);
  z-index: 2;
}

.mt-fiscal-banner .info-card.is-side-2 {
  opacity: 0.7;
  transform: scale(0.85) translateY(20px);
  z-index: 1;
}

.mt-fiscal-banner .info-card.is-side-3 {
  opacity: 0.6;
  transform: scale(0.8) translateY(30px);
  z-index: 0;
}

/* === Conteúdo Interno do Card Principal === */
.mt-fiscal-banner .card-badge {
  background-color: #1a4b8c; color: white; padding: 6px 12px;
  border-radius: 10px; font-size: 1.0rem; display: inline-flex;
  align-items: center; margin-bottom: 15px;
  max-width: 194px;
}
.mt-fiscal-banner .card-badge i { margin-right: 8px; font-size: 1.1em; }
.mt-fiscal-banner .card-title {
  font-size: 5rem; font-weight: 900; line-height: 1.1; color: #03237e;
  margin: 10px 0;
}
.mt-fiscal-banner .card-subtitle {
  font-size: 1.8rem; font-weight: bold; color: #2c4894; margin-top: 5px;
  text-transform: uppercase;
}
.mt-fiscal-banner .card-desc {
  font-size: 1.6rem; color: #7380c7; margin: -6px 0 25px 0;
}
/* === .mt-fiscal-banner .text-blue { color: #1d4e9e !important; } === */
.mt-fiscal-banner .btn-more {
  background: transparent; border: 1px solid #c9d5e3; color: #3b6cb9;
  padding: 10px 25px; border-radius: 5px; cursor: pointer;
  transition: all 0.3s; font-weight: bold;
  margin-top: auto;
  align-self: flex-start;
}
.mt-fiscal-banner .btn-more:hover { 
  background: #f7faff; 
  color: #4773C6;
}
.mt-fiscal-banner .btn-more.small {
  padding: 5px 12px; font-size: 0.7rem; width: auto; margin: 0 auto;
  display: inline-block;
}
.mt-fiscal-banner .indicators {
  display: flex;
  margin-top: 20px; padding-left: 246px;
}
.mt-fiscal-banner .indicators span {
  width: 9px; height: 9px; border-radius: 50%; background: rgba(255,255,255,0.4);
  margin: 0 4px; cursor: pointer; transition: all 0.3s;
}
.mt-fiscal-banner .indicators span.active { background: white; }

/* === Estilos para os cards da direita === */
.mt-fiscal-banner .stat-card {
  background: white; border-radius: 20px; box-shadow: 0 10px 30px rgba(0,0,0,0.2);
  overflow: hidden;
  transition: all 0.7s cubic-bezier(0.25, 0.8, 0.25, 1);
  cursor: pointer;
  opacity: 0;
  transform: scale(0.9) translateY(20px);
}

.mt-fiscal-banner .stat-card.visible {
  opacity: 1;
  transform: scale(1) translateY(0);
  max-height: 188px;
}

.mt-fiscal-banner .stat-card.hidden {
  opacity: 0;
  transform: scale(0.8) translateY(30px);
}

.mt-fiscal-banner .stat-header {
  padding: 10px 15px;
  margin: 10px 15px 5px -5px;
  width: calc(100% - 30px);
}

.mt-fiscal-banner .stat-badge {
  background-color: #1a4b8c; color: white; padding: 6px 12px;
  border-radius: 10px; font-size: 0.8rem; display: inline-flex;
  align-items: center;
}
.mt-fiscal-banner .stat-badge i { margin-right: 8px; font-size: 1.1em; }

.mt-fiscal-banner .stat-body {
  padding: 5px 15px 15px;
  text-align: center;
}

.mt-fiscal-banner .stat-value {
  color: #0a2674; font-size: 2.5rem; font-weight: 900;
  margin: 5px 0;
  text-align: left;
  transform: translate(0px, -26px);
}

.mt-fiscal-banner .stat-title {
  color: #405593; font-size: 1.2rem; font-weight: bold;
  margin: 5px 0;
  text-transform: uppercase;
  text-align: left;
  transform: translate(0px, -26px);
}

.mt-fiscal-banner .stat-desc-small {
  color: #98a1d1; font-size: 0.95rem; margin-top: 3px;
  margin-bottom: 10px;
  text-align: left;
  transform: translate(0px, -33px);
}

.mt-fiscal-banner .btn-more.small {
  padding: 5px 12px; font-size: 0.7rem; width: auto; margin: 0 auto;
  display: inline-block;
  background: transparent; border: 1px solid #c9d5e3; color: #3b6cb9;
  border-radius: 5px; cursor: pointer;
