/* Animação para o card que se move para o final */
.mt-fiscal-banner .stat-card.animate-move-to-end {
  animation: moveToLast 0.8s ease-out;
}

@keyframes moveToLast {
  0% {
    transform: scale(1) translateY(0);
    box-shadow: 0 10px 30px rgba(0,0,0,0.2);
  }
  50% {
    transform: scale(1.05) translateY(-5px);
    box-shadow: 0 15px 40px rgba(0,0,0,0.3);
  }
  100% {
    transform: scale(1) translateY(0);
    box-shadow: 0 10px 30px rgba(0,0,0,0.2);
  }
}

.card-viewport.high-contrast {
  background-color: #fff !important;
  color: #484848 !important;
}

.card-viewport.high-contrast .info-card {
  background-color: #fff !important;
  color: #484848 !important;
  border-radius: 25px !important;
  //overflow: hidden !important;
}

.card-viewport.high-contrast .info-card * {
  background-color: transparent !important;
  color: #484848 !important;
}

.card-viewport.high-contrast .card-badge {
  background-color: #838383 !important;
  color: white !important;
}

.card-viewport.high-contrast .card-badge * {
  background-color: transparent !important;
  color: white !important;
}

.card-viewport.high-contrast .btn-more {
  background-color: transparent !important;
  color: #484848 !important;
  border-color: #484848 !important;
}

.card-viewport {
  transition: background-color 0.3s ease, color 0.3s ease;
}

.stat-card.high-contrast {
  background-color: #fff !important;
  color: #484848 !important;
}

.stat-card.high-contrast .stat-badge {
  background-color: #838383 !important;
  color: white !important;
}

.stat-card.high-contrast .stat-badge * {
  background-color: transparent !important;
  color: white !important;
}

.stat-card.high-contrast * {
  background-color: transparent !important;
  color: #484848 !important;
}

.stat-card.high-contrast .btn-more.small {
  background-color: transparent !important;
  color: #484848 !important;
  border-color: #484848 !important;
}

.stat-card.high-contrast .btn-more.small:hover {
  background-color: #484848 !important;
  color: white !important;
  border-color: #484848 !important;
}

.stat-card {
  transition: background-color 0.3s ease, color 0.3s ease;
}



.card-viewport.high-contrast .btn-more:hover {
    background-color: #484848 !important; /* força o background */
    color: white !important; /* força a cor do texto */
    border-color: #484848 !important;
}

/* === Indicadores no modo contraste === */
.indicadoresPontos.high-contrast {
  background-color: #fff !important; /* pontos brancos */
  border: 1px solid #aaa !important; /* opcional, dá definição */
}

.indicadoresPontos.high-contrast.active {
  background-color: #888 !important; /* ponto ativo em cinza */
  border: 1px solid #555 !important;
}

/* ===== BADGE no modo contraste ===== */
.badge-cat.high-contrast {
  background-color: #838383 !important;
  color: black !important;
  padding: 6px 12px;
  border-radius: 6px;
}

